// ICSE 10 Mathematics ch11 Reflection — practice bank with independent re-solve checks.
// Keys and option values are typed as literals; each check recomputes them with refl.mjs: every image by the
// coordinate rule AND the perpendicular-bisector (or midpoint) definition, every invariant point by the rule
// AND "on the mirror", every mirror from a point and its image, every area by the shoelace formula AND Pick's
// theorem, every length exactly, every figure name from parallel sides, equal sides and right angles. Every
// typed working line in a solution or model answer is parsed and checked by work.mjs, and MCQ distractors
// are recomputed from the slip they represent.
import { Q, mk, r } from './lib.mjs';
import { pt, img, path, imgAll, X, Y, O, vx, hy, onMirror, mirrorsOf, singleFor, dist, dist2, area, perimeter, classify, collinear, same, mid, ct } from './refl.mjs';
import { steps, ARITH, eqctx, solvectx } from './work.mjs';

const J = (lines) => lines.join('\n\n');
const A = (lines) => steps(ARITH, lines);
const W = (ctx, lines) => steps(ctx, lines);
/** A number as a TeX factor: 3, (-2). */
const pn = (v) => (v < 0 ? `(${v})` : `${v}`);
/** Working line for the new coordinate in a line mirror: 2 × a − v = 2a − v. */
const tw = (a, v) => r`2 \times ${pn(a)} - ${pn(v)} = ${2 * a - v}`;
/** Coordinate pair options. */
const co = (ps) => ps.map((p) => `$${ct(p)}$`);
const P = (x, y) => pt(x, y);
/** Same point as a typed pair. */
const is = (p, q) => same(p, pt(q[0], q[1]));

// =============================================================== MCQ
const p01 = P(5, -7), o01 = [[5, 7], [-5, -7], [-5, 7], [-7, 5]];
Q('m01', mk.mcq({ stem: r`Under reflection in the $x$-axis, the point $(5, -7)$ is mapped to`, opts: co(o01), key: 'a', sol: r`Reflection in the $x$-axis keeps the $x$-coordinate and changes the sign of the $y$-coordinate: $(x, y) \to (x, -y)$, so $(5, -7)$ goes to $(5, 7)$. Option (b) is the image in the $y$-axis, (c) the image in the origin, and (d) swaps the coordinates.`, d: 1, c: 'recall', t: [1], time: 45 }), (C) => { C.assert(is(img(Y, p01), o01[1]) && is(img(O, p01), o01[2]), 'distractors (b), (c)'); C.which(o01, img(X, p01)); });

const p02 = P(-4, 9), o02 = [[4, 9], [-4, -9], [4, -9], [9, -4]];
Q('m02', mk.mcq({ stem: r`Which point is the mirror image of $Q(-4, 9)$ when the $y$-axis acts as the mirror?`, opts: co(o02), key: 'a', sol: r`Reflection in the $y$-axis changes only the sign of the $x$-coordinate: $(x, y) \to (-x, y)$, so the image is $(4, 9)$. Option (b) is the image in the $x$-axis and (c) the image in the origin.`, d: 1, c: 'recall', t: [1], time: 45 }), (C) => { C.assert(is(img(X, p02), o02[1]) && is(img(O, p02), o02[2]), 'distractors'); C.which(o02, img(Y, p02)); });

const p03 = P(6, -2), o03 = [[-6, 2], [6, 2], [-6, -2], [-2, 6]];
Q('m03', mk.mcq({ stem: r`Reflection in the origin sends $R(6, -2)$ to which point?`, opts: co(o03), key: 'a', sol: r`Reflection in the origin changes the signs of both coordinates: $(x, y) \to (-x, -y)$, giving $(-6, 2)$. Option (b) is the image in the $x$-axis and (c) the image in the $y$-axis; (d) swaps the coordinates as well.`, d: 1, c: 'recall', t: [2], time: 45 }), (C) => { C.assert(is(img(X, p03), o03[1]) && is(img(Y, p03), o03[2]), 'distractors'); C.which(o03, img(O, p03)); });

const p04 = P(7, 3), o04 = [[1, 3], [7, 5], [-7, 3], [11, 3]], w04 = A([tw(4, 7)]);
Q('m04', mk.mcq({ stem: r`A vertical mirror stands along the line $x = 4$. Where is the image of $A(7, 3)$?`, opts: co(o04), key: 'a', sol: r`The $y$-coordinate stays $3$, and the new $x$-coordinate is ${w04.md[0]}: $A$ is $3$ units to the right of the mirror, so its image is $3$ units to the left. Option (d) adds $4$ to $7$, (b) reflects in the line $y = 4$ instead, and (c) uses the $y$-axis as the mirror.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { w04.verify(C); C.assert(is(img(hy(4), p04), o04[1]) && is(img(Y, p04), o04[2]) && o04[3][0] === 7 + 4, 'distractors'); C.which(o04, img(vx(4), p04)); });

const p05 = P(-2, 5), o05 = [[-2, -7], [-2, -5], [-2, 3], [0, 5]], w05 = A([tw(-1, 5), r`5 - (-1) = 6`]);
Q('m05', mk.mcq({ stem: r`What are the coordinates of the image of $B(-2, 5)$ when it is reflected in the horizontal line $y = -1$?`, opts: co(o05), key: 'a', sol: r`The $x$-coordinate stays $-2$, and the new $y$-coordinate is ${w05.md[0]}: $B$ is ${w05.md[1]} units above the mirror, so the image is $6$ units below it. Option (b) reflects in the $x$-axis, (c) works out $2 \times (-1) + 5$, and (d) reflects in the line $x = -1$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { w05.verify(C); C.assert(is(img(X, p05), o05[1]) && o05[2][1] === 2 * -1 + 5 && is(img(vx(-1), p05), o05[3]), 'distractors'); C.which(o05, img(hy(-1), p05)); });

const p06 = P(-3, -8), o06 = [[-3, 8], [3, -8], [3, 8], [-8, -3]];
Q('m06', mk.mcq({ stem: r`After reflection in the $x$-axis, a point $P$ lands at $P'(-3, -8)$. Where was $P$?`, opts: co(o06), key: 'a', sol: r`Reflecting $P'$ in the $x$-axis again gives back $P$, so $P$ is $(-3, 8)$. Option (b) is the image of $P'$ in the $y$-axis, and (c) its image in the origin.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { const back = img(X, p06); C.assert(same(img(X, back), p06) && is(img(Y, p06), o06[1]) && is(img(O, p06), o06[2]), 'P maps to P′; distractors'); C.which(o06, back); });

const o07 = [[0, -6], [-6, 0], [6, 6], [-6, -6]];
Q('m07', mk.mcq({ stem: r`Which of these points does not move (is invariant) when the plane is reflected in the $y$-axis?`, opts: co(o07), key: 'a', sol: r`A point is invariant under reflection in the $y$-axis exactly when it lies on the $y$-axis, that is, when its $x$-coordinate is $0$. Only $(0, -6)$ qualifies; $(-6, 0)$ lies on the $x$-axis and moves to $(6, 0)$.`, d: 1, c: 'understanding', t: [3], time: 45 }), (C) => { C.assert(is(img(Y, P(-6, 0)), [6, 0]), '(−6, 0) moves'); C.which(o07.map((q) => (same(img(Y, P(...q)), P(...q)) && onMirror(Y, P(...q)) ? 'fixed' : 'moves')), 'fixed'); });

const o08 = [[-5, 3], [3, -5], [3, 0], [0, -3]];
Q('m08', mk.mcq({ stem: r`A mirror is placed along the line $y = 3$. Which point coincides with its own image?`, opts: co(o08), key: 'a', sol: r`Only points on the mirror line are their own images. Every point of the line $y = 3$ has $y$-coordinate $3$, so $(-5, 3)$ is invariant. Option (b) has $x$-coordinate $3$, which puts it on the line $x = 3$, not on $y = 3$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { C.which(o08.map((q) => (same(img(hy(3), P(...q)), P(...q)) ? 'fixed' : 'moves')), 'fixed'); C.assert(onMirror(vx(3), P(...o08[1])), '(b) is on x = 3'); });

const o09 = [O, X, Y, vx(1)], w09 = [P(4, 1), P(4, -1), P(-4, -1)];
Q('m09', mk.mcq({ stem: r`A point is reflected in the $x$-axis, and its image is then reflected in the $y$-axis. Which single reflection has the same overall effect?`, opts: o09.map((m) => m.tex), key: 'a', sol: r`$(x, y) \to (x, -y) \to (-x, -y)$: both signs change, which is exactly reflection in the origin. For example, $${ct(w09[0])} \to ${ct(w09[1])} \to ${ct(w09[2])}$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { C.assert(path(w09[0], X, Y).every((q, i) => same(q, w09[i])) && same(img(O, w09[0]), w09[2]), 'example'); C.which(o09.map((m) => m.eq), singleFor(X, Y)?.eq); });

const o10 = ['y = 3', 'x = 4', 'y = 4', 'y = 8'], w10 = A([r`\dfrac{7 + (-1)}{2} = 3`, r`\dfrac{7 + 1}{2} = 4`, r`7 - (-1) = 8`]);
Q('m10', mk.mcq({ stem: r`The point $(4, -1)$ is the image of $(4, 7)$ in a mirror line. What is the equation of the mirror line?`, opts: o10.map((e) => `$${e}$`), key: 'a', sol: r`The $x$-coordinates are equal, so the mirror is horizontal and lies halfway between the two points: ${w10.md[0]}. The mirror is $y = 3$. Option (c) works out ${w10.md[1]}, ignoring the minus sign, and (d) is the distance ${w10.md[2]} between the points.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { w10.verify(C); const ms = mirrorsOf(P(4, 7), P(4, -1)); C.assert(ms.length === 1, 'one mirror'); C.which(o10, ms[0].eq); });

const p11 = P(3, -4), o11 = [[-7, -4], [1, -4], [-3, -4], [3, 0]], w11 = A([tw(-2, 3)]);
Q('m11', mk.mcq({ stem: r`Reflection in the line $x = -2$ takes a point $M$ to $M'(3, -4)$. What are the coordinates of $M$?`, opts: co(o11), key: 'a', sol: r`Reflecting $M'$ in the same line gives back $M$. The $y$-coordinate stays $-4$, and the $x$-coordinate is ${w11.md[0]}. Option (b) uses the line $x = 2$, (c) uses the $y$-axis, and (d) reflects in the line $y = -2$.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { w11.verify(C); const m = img(vx(-2), p11); C.assert(same(img(vx(-2), m), p11) && is(img(vx(2), p11), o11[1]) && is(img(Y, p11), o11[2]) && is(img(hy(-2), p11), o11[3]), 'M maps to M′; distractors'); C.which(o11, m); });

const p12 = path(P(2, -6), O, X), o12 = [[-2, -6], [-2, 6], [2, 6], [2, -6]];
Q('m12', mk.mcq({ stem: r`$P(2, -6)$ is reflected in the origin to give $P_1$, and $P_1$ is then reflected in the $x$-axis to give $P_2$. Find $P_2$.`, opts: co(o12), key: 'a', sol: r`$P_1 = ${ct(p12[1])}$ (both signs change), then $P_2 = ${ct(p12[2])}$ (only the sign of the $y$-coordinate changes). Together the two steps act like a single reflection of $P$ in the $y$-axis. Option (b) stops at $P_1$.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { C.assert(is(p12[1], o12[1]) && is(img(X, p12[0]), o12[2]) && singleFor(O, X)?.eq === Y.eq, 'P1; distractor (c); single mirror is the y-axis'); C.which(o12, p12[2]); });

const s13 = P(-3, 3), f13 = [s13, img(X, s13), img(O, s13), img(Y, s13)], o13 = ['a square', 'a rhombus with no right angle', 'a kite', 'an isosceles trapezium'];
Q('m13', mk.mcq({ stem: r`The point $S(-3, 3)$ is reflected in the $x$-axis to $T$, in the origin to $U$, and in the $y$-axis to $V$. What kind of quadrilateral is $STUV$?`, opts: o13, key: 'a', sol: r`$T${ct(f13[1])}$, $U${ct(f13[2])}$, $V${ct(f13[3])}$. Each side is $6$ units long and is horizontal or vertical, so all four sides are equal and all four angles are right angles: $STUV$ is a square.`, d: 2, c: 'application', t: [3], time: 90 }), (C) => { C.assert(dist(f13[0], f13[1]) === 6 && dist(f13[1], f13[2]) === 6, 'sides 6'); C.which(['square', 'rhombus', 'kite', 'isosceles trapezium'], classify(f13)); });

const k14 = P(5, 3), t14 = [P(0, 0), k14, img(X, k14)], w14 = A([r`3 - (-3) = 6`, r`\dfrac{1}{2} \times 6 \times 5 = 15`, r`\dfrac{1}{2} \times 3 \times 5 = 7.5`, r`\dfrac{1}{2} \times 6 \times 3 = 9`]);
Q('m14', mk.mcq({ stem: r`$K(5, 3)$ is reflected in the $x$-axis to $K'$. What is the area of triangle $OKK'$, where $O$ is the origin?`, opts: ['$15$ square units', '$30$ square units', '$7.5$ square units', '$9$ square units'], key: 'a', sol: r`$K'$ is $${ct(t14[2])}$, so the base $KK' = ${w14.lines[0]}$ is vertical. The height is the distance of $O$ from the line $x = 5$, which is $5$. Area $= ${w14.lines[1]}$ square units. Option (b) forgets the half, (c) takes $3$ as the base, and (d) takes $3$ as the height.`, d: 2, c: 'application', t: [1, 3], time: 90 }), (C) => { w14.verify(C); C.which([15, 30, 7.5, 9], area(t14)); C.assert(dist(t14[1], t14[2]) === 6, 'KK′ = 6'); });

const p15 = P(-3, 4), o15 = [6, 8, 3, 10], w15 = A([r`3 - (-3) = 6`, r`2 \times 5 = 10`]);
Q('m15', mk.mcq({ stem: r`How far apart are $S(-3, 4)$ and its mirror image in the $y$-axis?`, opts: o15.map((v) => `$${v}$ units`), key: 'a', sol: r`The image is $${ct(img(Y, p15))}$, on the same horizontal line, so the distance is ${w15.md[0]} units: twice the distance of $S$ from the mirror. Option (b) doubles the $y$-coordinate, and (d) is the distance from $S$ to its image in the origin, ${w15.md[1]}.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { w15.verify(C); C.assert(dist(p15, img(O, p15)) === 10 && o15[1] === 2 * 4, 'distractors'); C.which(o15, dist(p15, img(Y, p15))); });

const rules16 = [(x, y, b) => [x, 2 * b - y], (x, y, b) => [2 * b - x, y], (x, y, b) => [x, b - y], (x, y, b) => [x, y - 2 * b]];
const w16 = W({ consts: {}, free: ['b', 'y'], sols: [], labels: {} }, [r`b - (y - b) = 2b - y`]);
Q('m16', mk.mcq({ stem: r`Which rule gives the image of a point $(x, y)$ under reflection in the horizontal line $y = b$?`, opts: [r`$(x, y) \to (x, 2b - y)$`, r`$(x, y) \to (2b - x, y)$`, r`$(x, y) \to (x, b - y)$`, r`$(x, y) \to (x, y - 2b)$`], key: 'a', sol: r`The $x$-coordinate does not change. The point is $y - b$ above the mirror, so its image is $y - b$ below it, at height ${w16.md[0]}. Check with $b = 0$: the rule becomes $(x, -y)$, reflection in the $x$-axis. Option (b) changes the wrong coordinate.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { w16.verify(C); const tests = [[3, 5, 2], [-4, 1, -3], [0, -7, 1], [6, 2, 0.5]]; C.which(rules16.map((f) => (tests.every(([x, y, b]) => same(P(...f(x, y, b)), img(hy(b), P(x, y)))) ? 'rule' : 'no')), 'rule'); });

const g17 = []; for (let x = -10; x <= 10; x += 0.5) for (let y = -10; y <= 10; y += 0.5) if (same(img(O, P(x, y)), P(x, y))) g17.push([x, y]);
Q('m17', mk.mcq({ stem: r`How many points of the plane are left unchanged by reflection in the origin?`, opts: ['exactly one, the origin', 'none', 'exactly two', 'infinitely many'], key: 'a', sol: r`A fixed point needs $(x, y)$ and $(-x, -y)$ to be the same point, so $x = -x$ and $y = -y$, which forces $x = 0$ and $y = 0$: only the origin is invariant. A line mirror, by contrast, has infinitely many invariant points.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { C.which([1, 0, 2, Infinity], g17.length); C.assert(g17.length === 1 && g17[0][0] === 0 && g17[0][1] === 0, 'brute force over a grid finds only the origin'); });

const u18 = P(1, 2), v18 = P(5, 5), w18 = A([r`\sqrt{4^2 + 3^2} = \sqrt{25} = 5`, r`4 + 3 = 7`]);
Q('m18', mk.mcq({ stem: r`The segment $UV$ joins $U(1, 2)$ and $V(5, 5)$. It is reflected in the $x$-axis to $U'V'$. How long is $U'V'$?`, opts: ['$5$ units', '$3$ units', '$4$ units', '$7$ units'], key: 'a', sol: r`$U'${ct(img(X, u18))}$ and $V'${ct(img(X, v18))}$, so $U'V' = ${w18.lines[0]}$ units, the same as $UV$: a reflection does not change lengths. Options (b) and (c) are the vertical and horizontal gaps on their own, and (d) adds them: ${w18.md[1]}.`, d: 2, c: 'application', t: [1, 3], time: 75 }), (C) => { w18.verify(C); const [a, b] = imgAll(X, [u18, v18]); C.assert(dist(u18, v18) === dist(a, b), 'length kept'); C.which([5, 3, 4, 7], dist(a, b)); });

// =============================================================== assertion-reason (keys a c d b a c)
Q('ar1', mk.ar({ a: r`The image of $(-6, 4)$ in the $y$-axis is $(6, 4)$.`, r: r`Reflection in the $y$-axis changes the sign of the $x$-coordinate and leaves the $y$-coordinate unchanged.`, key: 'c', sol: r`A is true: $(-6, 4) \to (6, 4)$. R is the rule for reflection in the $y$-axis, and applying it gives A, so R explains A.`, d: 1, c: 'understanding', t: [1] }), (C) => { C.assert(is(img(Y, P(-6, 4)), [6, 4]), 'A true'); C.key('c'); });

Q('ar2', mk.ar({ a: r`The point $(0, -5)$ is invariant under reflection in the $y$-axis.`, r: r`Every point on the $x$-axis is its own image when the $y$-axis is the mirror.`, key: 'a', sol: r`A is true: $(0, -5)$ lies on the $y$-axis, the mirror itself, so it does not move. R is false: a point such as $(3, 0)$ on the $x$-axis moves to $(-3, 0)$; only the origin stays fixed.`, d: 2, c: 'understanding', t: [3] }), (C) => { C.assert(same(img(Y, P(0, -5)), P(0, -5)) && is(img(Y, P(3, 0)), [-3, 0]), 'A true, R false'); C.key('a'); });

const war3 = A([tw(5, 3)]);
Q('ar3', mk.ar({ a: r`Reflecting $(3, 8)$ in the line $x = 5$ gives $(-3, 8)$.`, r: r`A mirror line is the perpendicular bisector of the segment that joins any point not on it to its image.`, key: 'b', sol: r`R is true. A is false: the new $x$-coordinate is ${war3.md[0]}, so the image is $(7, 8)$. The point $(-3, 8)$ is the image in the $y$-axis.`, d: 2, c: 'understanding', t: [2] }), (C) => { war3.verify(C); C.assert(is(img(vx(5), P(3, 8)), [7, 8]) && is(img(Y, P(3, 8)), [-3, 8]), 'A false'); C.key('b'); });

const par4 = path(P(4, -9), X, Y);
Q('ar4', mk.ar({ a: r`Reflecting $(4, -9)$ in the $x$-axis and then in the $y$-axis gives $(-4, 9)$.`, r: r`A point and its image are always at the same distance from the mirror.`, key: 'd', sol: r`A is true: $${ct(par4[0])} \to ${ct(par4[1])} \to ${ct(par4[2])}$. R is also true, but A follows from the two coordinate rules (together they act as reflection in the origin), not from equal distances, so R does not explain A.`, d: 2, c: 'analysis', t: [3] }), (C) => { C.assert(is(par4[2], [-4, 9]), 'A true'); C.key('d'); });

const war5 = A([r`7 - 1 = 6`, r`2 \times 6 = 12`]);
Q('ar5', mk.ar({ a: r`The point $(-2, 7)$ and its image in the line $y = 1$ are $12$ units apart.`, r: r`If a point is $k$ units from a mirror line, then the point and its image are $2k$ units apart.`, key: 'c', sol: r`$(-2, 7)$ is ${war5.md[0]} units above the mirror, so by R the two points are ${war5.md[1]} units apart; indeed the image is $${ct(img(hy(1), P(-2, 7)))}$. Both statements are true and R explains A.`, d: 2, c: 'application', t: [2] }), (C) => { war5.verify(C); C.assert(dist(P(-2, 7), img(hy(1), P(-2, 7))) === 12, 'A true'); C.key('c'); });

Q('ar6', mk.ar({ a: r`Reflection in the origin maps $(5, -1)$ to $(-5, 1)$.`, r: r`Reflection in the origin has the same effect as one reflection in the $x$-axis.`, key: 'a', sol: r`A is true: both signs change. R is false: reflection in the $x$-axis would give $(5, 1)$. Reflection in the origin equals reflection in the $x$-axis followed by reflection in the $y$-axis.`, d: 2, c: 'understanding', t: [2, 3] }), (C) => { C.assert(is(img(O, P(5, -1)), [-5, 1]) && is(img(X, P(5, -1)), [5, 1]) && singleFor(X, Y)?.eq === 'O', 'A true, R false'); C.key('a'); });

// =============================================================== true-false
const ptf1 = path(P(8, 1), vx(3), vx(3));
Q('tf1', mk.tf({ stem: r`Reflecting a point twice in the same mirror line always brings it back to its starting position.`, key: 't', sol: r`True. The second reflection undoes the first: in the line $x = 3$, $${ct(ptf1[0])} \to ${ct(ptf1[1])} \to ${ct(ptf1[2])}$.`, d: 1, c: 'understanding', t: [3] }), (C) => { C.assert(same(ptf1[0], ptf1[2]), 'back to the start'); C.key('t'); });

const wtf2 = A([tw(3, 3)]);
Q('tf2', mk.tf({ stem: r`Reflection in the line $x = 3$ moves the point $(3, -4)$ to $(-3, -4)$.`, key: 'f', sol: r`False. $(3, -4)$ lies on the mirror $x = 3$, so it is invariant: the new $x$-coordinate is ${wtf2.md[0]}, and the image is $(3, -4)$ itself.`, d: 2, c: 'understanding', t: [2, 3] }), (C) => { wtf2.verify(C); C.assert(same(img(vx(3), P(3, -4)), P(3, -4)), 'invariant'); C.key('f'); });

const ptf3 = path(P(2, -5), X, Y);
Q('tf3', mk.tf({ stem: r`The point $(2, -5)$ ends up in the same place whether it is reflected in the $x$-axis and then in the $y$-axis, or reflected once in the origin.`, key: 't', sol: r`True. $${ct(ptf3[0])} \to ${ct(ptf3[1])} \to ${ct(ptf3[2])}$, and reflection in the origin also gives $${ct(img(O, ptf3[0]))}$.`, d: 2, c: 'understanding', t: [3] }), (C) => { C.assert(same(ptf3[2], img(O, ptf3[0])), 'same point'); C.key('t'); });

const tri4 = [P(2, 1), P(6, 1), P(2, 4)], img4 = imgAll(Y, tri4), wtf4 = A([r`\dfrac{1}{2} \times 4 \times 3 = 6`]);
Q('tf4', mk.tf({ stem: r`A triangle and its image under reflection in the $y$-axis can have different areas.`, key: 'f', sol: r`False. A reflection keeps every length, so the image is congruent to the triangle. For example, the triangle with vertices ${tri4.map((p) => `$${ct(p)}$`).join(', ')} and its image ${img4.map((p) => `$${ct(p)}$`).join(', ')} both have area ${wtf4.md[0]} square units.`, d: 2, c: 'understanding', t: [3] }), (C) => { wtf4.verify(C); C.assert(area(tri4) === 6 && area(img4) === 6, 'equal areas'); C.key('f'); });

const wtf5 = A([tw(-1, -1)]);
Q('tf5', mk.tf({ stem: r`The point $(-1, 4)$ is its own image under reflection in the line $x = -1$.`, key: 't', sol: r`True. It lies on the mirror line $x = -1$; the new $x$-coordinate is ${wtf5.md[0]}.`, d: 1, c: 'understanding', t: [2, 3] }), (C) => { wtf5.verify(C); C.assert(same(img(vx(-1), P(-1, 4)), P(-1, 4)), 'invariant'); C.key('t'); });

const wtf6 = A([r`5 - (-3) = 8`, r`-3 - 8 = -11`, r`-3 - 5 = -8`]);
Q('tf6', mk.tf({ stem: r`Reflection in the line $y = -3$ sends $(0, 5)$ to $(0, -8)$.`, key: 'f', sol: r`False. $(0, 5)$ is ${wtf6.md[0]} units above the mirror, so its image is $8$ units below it, at height ${wtf6.md[1]}: the image is $(0, -11)$. The value $-8$ comes from ${wtf6.md[2]}.`, d: 2, c: 'application', t: [2] }), (C) => { wtf6.verify(C); C.assert(is(img(hy(-3), P(0, 5)), [0, -11]), 'image (0, −11)'); C.key('f'); });

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: r`Under reflection in the $y$-axis, $(-8, -3)$ becomes $(k, -3)$, where $k$ = ___.`, acc: [['8']], sol: r`The rule $(x, y) \to (-x, y)$ changes only the sign of the $x$-coordinate, so $k = 8$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.blank(img(Y, P(-8, -3))[0]); });

const wfb2 = A([tw(1, 5)]);
Q('fb2', mk.fill({ stem: r`When $(5, 2)$ is reflected in the vertical line $x = 1$, the $x$-coordinate of its image is ___.`, acc: [['-3', '−3']], sol: r`The new $x$-coordinate is ${wfb2.md[0]}, so the image is $(-3, 2)$.`, d: 2, c: 'understanding', t: [2] }), (C) => { wfb2.verify(C); C.blank(img(vx(1), P(5, 2))[0]); });

const wfb3 = A([tw(4, 1)]);
Q('fb3', mk.fill({ stem: r`The mirror line $y = 4$ maps $(-6, 1)$ to a point whose $y$-coordinate is ___.`, acc: [['7']], sol: r`The new $y$-coordinate is ${wfb3.md[0]}: the point is $3$ units below the mirror, so its image is $3$ units above it.`, d: 2, c: 'understanding', t: [2] }), (C) => { wfb3.verify(C); C.blank(img(hy(4), P(-6, 1))[1]); });

Q('fb4', mk.fill({ stem: r`The only point that reflection in the origin leaves fixed is ___.`, acc: [['the origin', 'origin', '(0, 0)', 'O']], sol: r`Only the origin $(0, 0)$ satisfies $(x, y) = (-x, -y)$.`, d: 1, c: 'recall', t: [3] }), (C) => { C.blank(same(img(O, P(0, 0)), P(0, 0)) && !same(img(O, P(1, 0)), P(1, 0)) ? 'the origin' : 'none'); });

Q('fb5', mk.fill({ stem: r`If the image of $(4, -7)$ in the $x$-axis is written as $(4, k)$, the value of $k$ is ___.`, acc: [['7']], sol: r`Reflection in the $x$-axis changes the sign of the $y$-coordinate: $k = 7$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.blank(img(X, P(4, -7))[1]); });

const wfb6 = A([r`\dfrac{9 + (-3)}{2} = 3`]);
Q('fb6', mk.fill({ stem: r`$P(2, 9)$ and $P'(2, -3)$ are mirror images of each other in the line $y = c$. Then $c$ = ___.`, acc: [['3']], sol: r`The mirror lies halfway between them: $c = ${wfb6.lines[0]}$.`, d: 2, c: 'application', t: [2] }), (C) => { wfb6.verify(C); C.blank(mirrorsOf(P(2, 9), P(2, -3))[0].b); });

// =============================================================== numerical
const tn1 = P(6, -8), wn1 = A([r`\sqrt{6^2 + 8^2} = \sqrt{100} = 10`, r`2 \times 10 = 20`]);
Q('n01', mk.num({ stem: r`Find the distance between $T(6, -8)$ and its image under reflection in the origin.`, value: 20, sol: r`The image is $T'${ct(img(O, tn1))}$, and $O$ is the midpoint of $TT'$. $OT = ${wn1.lines[0]}$, so $TT' = ${wn1.lines[1]}$ units.`, scheme: [['20 units', 1]], d: 2, c: 'application', t: [2], time: 75 }), (C) => { wn1.verify(C); C.val(dist(tn1, img(O, tn1))); });

const pn2 = P(4, 1), fn2 = [pn2, img(Y, pn2), img(X, pn2)], wn2 = A([r`4 - (-4) = 8`, r`1 - (-1) = 2`, r`\dfrac{1}{2} \times 8 \times 2 = 8`]);
Q('n02', mk.num({ marks: 2, stem: r`$P(4, 1)$ is reflected in the $y$-axis to $P'$ and in the $x$-axis to $P''$. Find the area of triangle $PP'P''$ in square units.`, value: 8, sol: r`$P'${ct(fn2[1])}$ and $P''${ct(fn2[2])}$. The angle at $P$ is a right angle ($PP'$ is horizontal and $PP''$ vertical), with $PP' = ${wn2.lines[0]}$ and $PP'' = ${wn2.lines[1]}$. Area $= ${wn2.lines[2]}$ square units.`, scheme: [['P′(−4, 1) and P″(4, −1)', 1], ['Area 8 square units', 1]], d: 2, c: 'application', t: [1, 3], time: 120 }), (C) => { wn2.verify(C); C.assert(classify(fn2) === 'right-angled triangle', 'right angle at P'); C.val(area(fn2)); });

const wn3 = W(eqctx('k', [5]), [r`2 \times 5 - k = k \Rightarrow 2k = 10 \Rightarrow k = 5`]);
Q('n03', mk.num({ stem: r`For what value of $k$ is the point $(k, -2)$ invariant under reflection in the line $x = 5$?`, value: 5, sol: r`An invariant point is its own image: ${wn3.md[0]}. (It lies on the mirror.)`, scheme: [['k = 5', 1]], d: 2, c: 'application', t: [2, 3], time: 60 }), (C) => { wn3.verify(C); const ks = []; for (let k = -20; k <= 20; k += 0.5) if (same(img(vx(5), P(k, -2)), P(k, -2))) ks.push(k); C.assert(ks.length === 1, 'one value by search'); C.val(ks[0]); });

const wn4 = W(solvectx(['a', 'b'], { a: -3, b: -2 }), [r`2a + 1 = -5 \Rightarrow a = -3`, r`3b = -6 \Rightarrow b = -2`, r`a + b = -3 + (-2) = -5`]);
Q('n04', mk.num({ marks: 2, stem: r`The image of $(2a + 1, 6)$ in the $x$-axis is $(-5, 3b)$. Find the value of $a + b$.`, value: -5, sol: r`Reflection in the $x$-axis gives $(2a + 1, -6)$. Comparing coordinates: ${wn4.md[0]}, and ${wn4.md[1]}. So ${wn4.md[2]}.`, scheme: [['a = −3 and b = −2', 1], ['a + b = −5', 1]], d: 3, c: 'application', t: [1], time: 120 }), (C) => { wn4.verify(C); const a = -3, b = -2; C.assert(is(img(X, P(2 * a + 1, 6)), [-5, 3 * b]), 'substituted back'); C.val(a + b); });

const an5 = P(4, 3), bn5 = img(hy(1), an5), cn5 = img(Y, bn5), dn5 = img(Y, an5), wn5 = A([r`3 - (-1) = 4`, r`4 - (-4) = 8`, r`2 \times (8 + 4) = 24`]);
Q('n05', mk.num({ marks: 2, stem: r`$A(4, 3)$ is reflected in the line $y = 1$ to $B$; $B$ is reflected in the $y$-axis to $C$; and $D$ is the image of $A$ in the $y$-axis. Find the perimeter of the rectangle $ABCD$.`, value: 24, sol: r`$B${ct(bn5)}$, $C${ct(cn5)}$, $D${ct(dn5)}$. $AB = ${wn5.lines[0]}$ and $BC = ${wn5.lines[1]}$, so the perimeter is ${wn5.md[2]} units.`, scheme: [['B(4, −1), C(−4, −1), D(−4, 3)', 1], ['Perimeter 24 units', 1]], d: 3, c: 'application', t: [2, 3], time: 150 }), (C) => { wn5.verify(C); const f = [an5, bn5, cn5, dn5]; C.assert(classify(f) === 'rectangle', 'rectangle'); C.val(perimeter(f)); });

const pn6 = P(-3, 7), wn6 = A([r`2 - (-3) = 5`, r`2 \times 5 = 10`]);
Q('n06', mk.num({ stem: r`How far is the point $(-3, 7)$ from its image in the line $x = 2$?`, value: 10, sol: r`The point is ${wn6.md[0]} units from the mirror, so it is ${wn6.md[1]} units from its image $${ct(img(vx(2), pn6))}$.`, scheme: [['10 units', 1]], d: 2, c: 'application', t: [2], time: 60 }), (C) => { wn6.verify(C); C.val(dist(pn6, img(vx(2), pn6))); });

const gn7 = img(hy(-2), P(5, -9)), wn7 = A([tw(-2, -9), r`5 - (-9) = 14`]);
Q('n07', mk.num({ marks: 2, stem: r`Under reflection in the line $y = -2$, the image of a point $G$ is $G'(5, -9)$. Find the length of $GG'$.`, value: 14, sol: r`Reflect $G'$ back: the $y$-coordinate of $G$ is ${wn7.md[0]}, so $G${ct(gn7)}$. Then $GG' = ${wn7.lines[1]}$ units.`, scheme: [['G(5, 5)', 1], ['GG′ = 14 units', 1]], d: 3, c: 'application', t: [2], time: 120 }), (C) => { wn7.verify(C); C.assert(is(img(hy(-2), gn7), [5, -9]), 'G maps to G′'); C.val(dist(gn7, P(5, -9))); });

// =============================================================== short answer, 2 marks
const a201 = P(-4, 6);
Q('s201', mk.short({ marks: 2, stem: r`Write down the images of $A(-4, 6)$ under reflection in
(i) the $x$-axis,
(ii) the origin.`, model: J([r`(i) The sign of the $y$-coordinate changes: the image is $${ct(img(X, a201))}$.`, r`(ii) Both signs change: the image is $${ct(img(O, a201))}$.`]), sol: r`Use $(x, y) \to (x, -y)$ for the $x$-axis and $(x, y) \to (-x, -y)$ for the origin.`, scheme: [['(i) (−4, −6)', 1], ['(ii) (4, −6)', 1]], d: 1, c: 'understanding', t: [1, 2], time: 60 }), (C) => { C.model([ct([-4, -6]), ct([4, -6])]); C.assert(is(img(X, a201), [-4, -6]) && is(img(O, a201), [4, -6]), 'images'); });

const q202 = P(9, -1), w202 = A([tw(6, 9), tw(-4, -1)]);
Q('s202', mk.short({ marks: 2, stem: r`Find the image of $Q(9, -1)$ in
(i) the line $x = 6$,
(ii) the line $y = -4$.`, model: J([r`(i) The $y$-coordinate stays $-1$; the new $x$-coordinate is ${w202.md[0]}. Image: $${ct(img(vx(6), q202))}$.`, r`(ii) The $x$-coordinate stays $9$; the new $y$-coordinate is ${w202.md[1]}. Image: $${ct(img(hy(-4), q202))}$.`]), sol: r`In $x = a$ the image of $(x, y)$ is $(2a - x, y)$; in $y = b$ it is $(x, 2b - y)$.`, scheme: [['(i) (3, −1)', 1], ['(ii) (9, −7)', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { w202.verify(C); C.model([ct([3, -1]), ct([9, -7])]); C.assert(is(img(vx(6), q202), [3, -1]) && is(img(hy(-4), q202), [9, -7]), 'images'); });

const p203 = img(Y, P(-2, -7));
Q('s203', mk.short({ marks: 2, stem: r`A point $P$ is reflected in the $y$-axis, and its image is $(-2, -7)$. Find $P$, and then the image of $P$ in the origin.`, model: J([r`Reflecting the image back in the $y$-axis gives $P${ct(p203)}$.`, r`The image of $P$ in the origin is $${ct(img(O, p203))}$.`]), sol: r`A reflection undoes itself, so reflect the given image in the $y$-axis to recover $P$.`, scheme: [['P(2, −7)', 1], ['Image in the origin (−2, 7)', 1]], d: 2, c: 'application', t: [1, 2], time: 90 }), (C) => { C.assert(is(img(Y, p203), [-2, -7]), 'P maps to the image'); C.model([ct([2, -7]), ct([-2, 7])]); C.assert(is(img(O, p203), [-2, 7]), 'origin image'); });

const pts204 = { A: P(0, 4), B: P(4, 0), C: P(-4, 4) };
const inv204 = (m) => Object.entries(pts204).filter(([, p]) => same(img(m, p), p)).map(([k]) => k).join(' ');
Q('s204', mk.short({ marks: 2, stem: r`Which of the points $A(0, 4)$, $B(4, 0)$ and $C(-4, 4)$ are invariant under reflection in
(i) the $y$-axis,
(ii) the line $y = 4$?`, model: J([r`(i) Only $A$: it is the only one of the three with $x$-coordinate $0$, so it lies on the $y$-axis.`, r`(ii) $A$ and $C$: both have $y$-coordinate $4$, so they lie on the mirror. $B$ moves to $${ct(img(hy(4), pts204.B))}$.`]), sol: r`A point is invariant exactly when it lies on the mirror line.`, scheme: [['(i) A only', 1], ['(ii) A and C', 1]], d: 2, c: 'understanding', t: [3], time: 75 }), (C) => { C.assert(inv204(Y) === 'A' && inv204(hy(4)) === 'A C', 'invariant sets'); C.model([ct([4, 8])]); });

const m205 = mirrorsOf(P(-5, -3), P(1, -3)), w205 = A([r`\dfrac{-5 + 1}{2} = -2`, tw(-2, 2)]);
Q('s205', mk.short({ marks: 2, stem: r`$P(-5, -3)$ has image $P'(1, -3)$ in a mirror line. Find the mirror line, and the image of $(2, 8)$ in it.`, model: J([r`The $y$-coordinates are equal, so the mirror is vertical, halfway between: ${w205.md[0]}. The mirror is the line $x = -2$.`, r`Image of $(2, 8)$: the new $x$-coordinate is ${w205.md[1]}, so the image is $${ct(img(m205[0], P(2, 8)))}$.`]), sol: r`The mirror is the perpendicular bisector of $PP'$; then use $(x, y) \to (2a - x, y)$.`, scheme: [['x = −2', 1], ['(−6, 8)', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { w205.verify(C); C.assert(m205.length === 1 && m205[0].eq === 'x = -2', 'mirror x = −2'); C.model([ct([-6, 8])]); C.assert(is(img(m205[0], P(2, 8)), [-6, 8]), 'image'); });

// =============================================================== short answer, 3 marks
const p301 = path(P(-4, 3), X, Y), w301 = A([r`\sqrt{4^2 + 3^2} = 5`, r`2 \times 5 = 10`]);
Q('s301', mk.short({ marks: 3, stem: r`$P(-4, 3)$ is reflected in the $x$-axis to $P'$, and $P'$ is reflected in the $y$-axis to $P''$.
(i) Write the coordinates of $P'$ and $P''$.
(ii) Name the single transformation that maps $P$ to $P''$.
(iii) Find the length $PP''$.`, model: J([r`(i) $P'${ct(p301[1])}$ and $P''${ct(p301[2])}$.`, r`(ii) Both coordinates of $P$ have changed sign, so the single transformation is reflection in the origin.`, r`(iii) $O$ is the midpoint of $PP''$ and $OP = ${w301.lines[0]}$, so $PP'' = ${w301.lines[1]}$ units.`]), sol: r`Apply the two axis rules one after the other; a change of both signs is reflection in the origin, which makes $O$ the midpoint.`, scheme: [['(i) P′(−4, −3), P″(4, −3)', 1], ['(ii) reflection in the origin', 1], ['(iii) PP″ = 10 units', 1]], d: 2, c: 'application', t: [1, 3], time: 180 }), (C) => { w301.verify(C); C.assert(singleFor(X, Y).eq === 'O' && same(p301[2], img(O, p301[0])), 'single = origin'); C.model([ct([-4, -3]), ct([4, -3]), 10]); C.assert(dist(p301[0], p301[2]) === 10 && same(mid(p301[0], p301[2]), [0, 0]), 'PP″ = 10, midpoint O'); });

const p302 = path(P(-1, 5), vx(2), hy(-1)), w302 = A([tw(2, -1), tw(-1, 5), r`5 - (-1) = 6`, r`5 - (-7) = 12`, r`\dfrac{1}{2} \times 6 \times 12 = 36`]);
Q('s302', mk.short({ marks: 3, stem: r`$A(-1, 5)$ is reflected in the line $x = 2$ to $A'$, and $A'$ is reflected in the line $y = -1$ to $A''$. Find $A'$ and $A''$, and the area of triangle $AA'A''$.`, model: J([r`New $x$-coordinate in $x = 2$: ${w302.md[0]}, so $A'${ct(p302[1])}$.`, r`New $y$-coordinate in $y = -1$: ${w302.md[1]}, so $A''${ct(p302[2])}$.`, r`$AA'$ is horizontal and $A'A''$ vertical, so the angle at $A'$ is a right angle. $AA' = ${w302.lines[2]}$, $A'A'' = ${w302.lines[3]}$, and the area is ${w302.md[4]} square units.`]), sol: r`One mirror is vertical and the other horizontal, so the two segments $AA'$ and $A'A''$ are perpendicular legs of the triangle.`, scheme: [["A′(5, 5)", 1], ["A″(5, −7)", 1], ['Area 36 square units', 1]], d: 3, c: 'application', t: [2, 3], time: 210 }), (C) => { w302.verify(C); C.assert(classify(p302) === 'right-angled triangle', 'right angle at A′'); C.model([ct([5, 5]), ct([5, -7]), 36]); C.assert(area(p302) === 36, 'area 36'); });

const p2_303 = P(-6, 2), p1_303 = img(X, p2_303), p303 = img(O, p1_303);
Q('s303', mk.short({ marks: 3, stem: r`A point $P(a, b)$ is reflected in the origin to $P_1$, and $P_1$ is reflected in the $x$-axis to $P_2(-6, 2)$. Find $a$ and $b$, and name the single reflection that maps $P$ to $P_2$.`, model: J([r`Work backwards. Reflecting $P_2$ in the $x$-axis gives $P_1${ct(p1_303)}$.`, r`Reflecting $P_1$ in the origin gives $P${ct(p303)}$, so $a = 6$ and $b = 2$.`, r`$P${ct(p303)}$ and $P_2${ct(p2_303)}$ differ only in the sign of the $x$-coordinate, so the single reflection is in the $y$-axis.`]), sol: r`Each reflection undoes itself, so undo the steps in reverse order; then compare $P$ with $P_2$.`, scheme: [['P₁(−6, −2)', 1], ['a = 6, b = 2', 1], ['reflection in the y-axis', 1]], d: 3, c: 'analysis', t: [3], time: 180 }), (C) => { C.assert(same(path(p303, O, X)[2], p2_303) && singleFor(O, X).eq === 'x = 0', 'forward check; single = y-axis'); C.model([ct([-6, -2]), ct([6, 2]), 'y$-axis']); });

const w304 = W(solvectx(['p', 'q'], { p: 3, q: -5 }), [r`3p - 2 = 7 \Rightarrow 3p = 9 \Rightarrow p = 3`, r`q + 3 = -2 \Rightarrow q = -5`]), w304b = A([tw(1, 4)]);
Q('s304', mk.short({ marks: 3, stem: r`The image of $(3p - 2, 4)$ under reflection in the line $y = 1$ is $(7, q + 3)$. Find $p$ and $q$.`, model: J([r`In $y = 1$ the $x$-coordinate is kept and the new $y$-coordinate is ${w304b.md[0]}, so the image is $(3p - 2, -2)$.`, r`Comparing $x$-coordinates: ${w304.md[0]}.`, r`Comparing $y$-coordinates: ${w304.md[1]}.`]), sol: r`Write the image with the rule for $y = b$, then compare the coordinates one at a time.`, scheme: [['Image (3p − 2, −2)', 1], ['p = 3', 1], ['q = −5', 1]], d: 3, c: 'application', t: [2], time: 150 }), (C) => { w304.verify(C); w304b.verify(C); C.assert(is(img(hy(1), P(3 * 3 - 2, 4)), [7, -5 + 3]), 'substituted back'); C.model([3, -5]); });

const t305 = [P(1, 2), P(5, 2), P(1, 6)], i305 = imgAll(vx(-1), t305), w305 = A([tw(-1, 1), tw(-1, 5), r`\dfrac{1}{2} \times 4 \times 4 = 8`]);
Q('s305', mk.short({ marks: 3, stem: r`Triangle $LMN$ has vertices $L(1, 2)$, $M(5, 2)$ and $N(1, 6)$. It is reflected in the line $x = -1$. Write the vertices of the image $L'M'N'$, and show that the two triangles have the same area.`, model: J([r`New $x$-coordinates: ${w305.md[0]} and ${w305.md[1]}; the $y$-coordinates are kept. So $L'${ct(i305[0])}$, $M'${ct(i305[1])}$, $N'${ct(i305[2])}$.`, r`In each triangle one side is horizontal and one vertical, of lengths $4$ and $4$.`, r`So each area is ${w305.md[2]} square units: the areas are equal, as a reflection keeps lengths.`]), sol: r`Reflect each vertex with $(x, y) \to (2a - x, y)$; the image triangle is congruent to the original.`, scheme: [["L′, M′, N′", 1], ['Area of LMN = 8', 1], ["Area of L′M′N′ = 8", 1]], d: 2, c: 'application', t: [2, 3], time: 180 }), (C) => { w305.verify(C); C.model([ct([-3, 2]), ct([-7, 2]), ct([-3, 6]), 8]); C.assert(area(t305) === 8 && area(i305) === 8, 'equal areas'); });

// =============================================================== short answer, 4 marks
const a401 = P(4, 2), b401 = img(X, a401), c401 = img(O, b401), f401 = [a401, b401, c401], w401 = A([r`2 - (-2) = 4`, r`4 - (-4) = 8`, r`\dfrac{1}{2} \times 4 \times 8 = 16`]);
Q('s401', mk.short({ marks: 4, stem: r`On graph paper, plot $A(4, 2)$. Reflect $A$ in the $x$-axis to get $B$, and reflect $B$ in the origin to get $C$.
(i) Write the coordinates of $B$ and $C$.
(ii) Name triangle $ABC$ and find its area.`, model: J([r`(i) $B${ct(b401)}$ and $C${ct(c401)}$.`, r`(ii) $AB$ is vertical and $AC$ is horizontal, so the angle at $A$ is a right angle: $ABC$ is a right-angled triangle.`, r`$AB = ${w401.lines[0]}$ and $AC = ${w401.lines[1]}$, so its area is ${w401.md[2]} square units.`]), sol: r`Plot each point as it is found; the right angle shows at once because one leg is vertical and the other horizontal.`, scheme: [['B(4, −2)', 1], ['C(−4, 2)', 1], ['right-angled triangle', 1], ['Area 16 square units', 1]], d: 2, c: 'application', t: [1, 2, 3], time: 240 }), (C) => { w401.verify(C); C.assert(classify(f401) === 'right-angled triangle' && same(c401, img(Y, a401)), 'right angle; C is also the y-axis image of A'); C.model([ct([4, -2]), ct([-4, 2]), 16]); C.assert(area(f401) === 16, 'area'); });

const t402 = { P: P(1, 1), Q: P(4, 1), R: P(1, 3) }, r402 = img(hy(1), t402.R), f402 = [t402.R, t402.Q, r402], w402 = A([tw(1, 3), r`3 - (-1) = 4`, r`4 - 1 = 3`, r`\dfrac{1}{2} \times 4 \times 3 = 6`]);
Q('s402', mk.short({ marks: 4, stem: r`Triangle $PQR$ has vertices $P(1, 1)$, $Q(4, 1)$ and $R(1, 3)$. It is reflected in the line $y = 1$.
(i) Which vertices are invariant?
(ii) Write the image $R'$ of $R$.
(iii) Name the figure $RQR'$ and find its area.`, model: J([r`(i) $P$ and $Q$ have $y$-coordinate $1$, so they lie on the mirror and are invariant.`, r`(ii) The new $y$-coordinate of $R$ is ${w402.md[0]}, so $R'${ct(r402)}$.`, r`(iii) $QR = QR'$ (a reflection keeps lengths), so $RQR'$ is an isosceles triangle. Its base $RR' = ${w402.lines[1]}$ lies on the line $x = 1$, and its height is the distance of $Q$ from that line, ${w402.md[2]}.`, r`Area $= ${w402.lines[3]}$ square units.`]), sol: r`Vertices on the mirror stay where they are; the triangle and its image together make a figure that is symmetric about the mirror.`, scheme: [['P and Q invariant', 1], ["R′(1, −1)", 1], ['isosceles triangle', 1], ['Area 6 square units', 1]], d: 3, c: 'analysis', t: [2, 3], time: 240 }), (C) => { w402.verify(C); C.assert(same(img(hy(1), t402.P), t402.P) && same(img(hy(1), t402.Q), t402.Q) && !same(r402, t402.R), 'P, Q fixed; R moves'); C.assert(classify(f402) === 'isosceles triangle' && collinear(t402.R, t402.P, r402), 'isosceles; P on RR′'); C.model([ct([1, -1]), 6]); C.assert(area(f402) === 6, 'area'); });

const m403 = mirrorsOf(P(5, -2), P(-1, -2)), w403 = A([r`\dfrac{5 + (-1)}{2} = 2`, tw(2, -4)]);
Q('s403', mk.short({ marks: 4, stem: r`The point $P(5, -2)$ is reflected in a line $l$ to $P'(-1, -2)$.
(i) Find the equation of $l$.
(ii) Find the image of $Q(-4, 7)$ in $l$.
(iii) Give two points of $l$ that are invariant under this reflection.`, model: J([r`(i) $P$ and $P'$ have the same $y$-coordinate, so $l$ is vertical and passes through the midpoint of $PP'$: ${w403.md[0]}. So $l$ is $x = 2$.`, r`(ii) New $x$-coordinate: ${w403.md[1]}; the $y$-coordinate stays $7$. The image of $Q$ is $${ct(img(m403[0], P(-4, 7)))}$.`, r`(iii) Every point of $l$ is invariant, for example $(2, 0)$ and $(2, -2)$ (the midpoint of $PP'$).`]), sol: r`The mirror is the perpendicular bisector of $PP'$; then reflect $Q$ in it; invariant points are exactly the points on the mirror.`, scheme: [['l: x = 2', 1], ['Q′(8, 7)', 1], ['two points with x = 2', 2]], d: 2, c: 'application', t: [2, 3], time: 210 }), (C) => { w403.verify(C); C.assert(m403.length === 1 && m403[0].eq === 'x = 2', 'l: x = 2'); C.assert(same(img(m403[0], P(2, 0)), P(2, 0)) && same(img(m403[0], P(2, -2)), P(2, -2)), 'invariant examples'); C.model(['x = 2', ct([8, 7])]); C.assert(is(img(m403[0], P(-4, 7)), [8, 7]), 'Q′'); });

const p404 = path(P(-2, 3), vx(1), Y), m404 = mirrorsOf(p404[0], p404[2]), w404 = A([tw(1, -2), r`\dfrac{-2 + (-4)}{2} = -3`, r`4 - (-2) = 6`, r`4 - (-4) = 8`]);
Q('s404', mk.short({ marks: 4, stem: r`$A(-2, 3)$ is reflected in the line $x = 1$ to $B$, and $B$ is reflected in the $y$-axis to $C$.
(i) Find $B$ and $C$.
(ii) Find the single mirror line that reflects $A$ directly onto $C$.
(iii) Find the lengths $AB$ and $BC$.`, model: J([r`(i) New $x$-coordinate in $x = 1$: ${w404.md[0]}, so $B${ct(p404[1])}$; then in the $y$-axis $C${ct(p404[2])}$.`, r`(ii) $A$ and $C$ have the same $y$-coordinate, so the mirror is vertical, through the midpoint: ${w404.md[1]}. The line is $x = -3$.`, r`(iii) All three points lie on the line $y = 3$: $AB = ${w404.lines[2]}$ units and $BC = ${w404.lines[3]}$ units.`]), sol: r`Two reflections in parallel lines move a point along the same horizontal line; a single mirror for $A$ and $C$ is the perpendicular bisector of $AC$.`, scheme: [['B(4, 3)', 1], ['C(−4, 3)', 1], ['x = −3', 1], ['AB = 6, BC = 8', 1]], d: 4, c: 'analysis', t: [2, 3], time: 240 }), (C) => { w404.verify(C); C.assert(m404.length === 1 && m404[0].eq === 'x = -3' && collinear(...p404), 'mirror x = −3; collinear'); C.model([ct([4, 3]), ct([-4, 3]), 'x = -3', 6, 8]); C.assert(dist(p404[0], p404[1]) === 6 && dist(p404[1], p404[2]) === 8, 'lengths'); });

const w405 = W(eqctx('m', [4]), [r`-m = -4 \Rightarrow m = 4`]), w405b = A([r`2 \times 4 - 1 = 7`, r`4 - (-4) = 8`]);
const p405 = P(4, 7);
Q('s405', mk.short({ marks: 4, stem: r`The point $(m, 2m - 1)$ has image $(-4, n)$ under reflection in the $y$-axis.
(i) Find $m$ and $n$.
(ii) Find the distance between the point and its image.
(iii) Write the image of the point under reflection in the origin.`, model: J([r`(i) The $y$-axis image of $(m, 2m - 1)$ is $(-m, 2m - 1)$. Comparing: ${w405.md[0]}, and $n = 2m - 1 = ${w405b.lines[0]}$. The point is $${ct(p405)}$.`, r`(ii) The point $${ct(p405)}$ and its image $${ct(img(Y, p405))}$ lie on the same horizontal line, so the distance is ${w405b.md[1]} units.`, r`(iii) Reflection in the origin gives $${ct(img(O, p405))}$.`]), sol: r`Write the image with the $y$-axis rule and compare coordinates; then use the coordinates found.`, scheme: [['m = 4', 1], ['n = 7', 1], ['distance 8 units', 1], ['(−4, −7)', 1]], d: 3, c: 'application', t: [1, 2], time: 210 }), (C) => { w405.verify(C); w405b.verify(C); C.assert(is(img(Y, P(4, 2 * 4 - 1)), [-4, 7]), 'substituted back'); C.model([4, 7, 8, ct([-4, -7])]); C.assert(dist(p405, img(Y, p405)) === 8 && is(img(O, p405), [-4, -7]), 'distance, origin image'); });

const e406 = P(2, 5), f406 = P(5, 1), [e2, f2] = imgAll(Y, [e406, f406]), fig406 = [e406, f406, f2, e2], w406 = A([r`2 - (-2) = 4`, r`5 - (-5) = 10`, r`\sqrt{3^2 + 4^2} = 5`, r`\dfrac{1}{2} \times (4 + 10) \times 4 = 28`, r`4 + 5 + 10 + 5 = 24`]);
Q('s406', mk.short({ marks: 4, stem: r`The segment joining $E(2, 5)$ and $F(5, 1)$ is reflected in the $y$-axis to $E'F'$.
(i) Write the coordinates of $E'$ and $F'$.
(ii) Name the figure $EFF'E'$.
(iii) Find its area and its perimeter.`, model: J([r`(i) $E'${ct(e2)}$ and $F'${ct(f2)}$.`, r`(ii) $EE'$ and $FF'$ are both horizontal, so they are parallel, while $EF = E'F'$ (a reflection keeps lengths): $EFF'E'$ is an isosceles trapezium.`, r`(iii) $EE' = ${w406.lines[0]}$, $FF' = ${w406.lines[1]}$, and the distance between these parallel sides is $5 - 1 = 4$. Area $= ${w406.lines[3]}$ square units.`, r`$EF = ${w406.lines[2]}$, so the perimeter is ${w406.md[4]} units.`]), sol: r`The two parallel sides are the horizontal segments $EE'$ and $FF'$; the slanted sides are a segment and its image, so they are equal.`, scheme: [["E′(−2, 5), F′(−5, 1)", 1], ['isosceles trapezium', 1], ['Area 28 square units', 1], ['Perimeter 24 units', 1]], d: 3, c: 'application', t: [1, 3], time: 240 }), (C) => { w406.verify(C); C.assert(classify(fig406) === 'isosceles trapezium', 'isosceles trapezium'); C.model([ct([-2, 5]), ct([-5, 1]), 28, 24]); C.assert(area(fig406) === 28 && perimeter(fig406) === 24, 'area 28, perimeter 24'); });

// =============================================================== long, 10 marks
const pl1 = P(4, 3), ql1 = P(1, -2), [pl1b, ql1b] = imgAll(Y, [pl1, ql1]), tl1 = [pl1, ql1, ql1b, pl1b], pl1c = img(X, pl1b);
const wl1 = A([r`4 - (-4) = 8`, r`1 - (-1) = 2`, r`3 - (-2) = 5`, r`\dfrac{1}{2} \times (8 + 2) \times 5 = 25`, r`\sqrt{4^2 + 3^2} = 5`, r`2 \times 5 = 10`]);
Q('l01', mk.long({ marks: 10, stem: r`Use graph paper for this question (take $1$ cm $= 1$ unit on both axes).
(a) Plot $P(4, 3)$ and $Q(1, -2)$. Reflect both points in the $y$-axis to get $P'$ and $Q'$, and write their coordinates.
(b) Name the figure $PQQ'P'$ and find its area.
(c) $P'$ is reflected in the $x$-axis to $P''$. Name the single transformation that maps $P$ to $P''$, and find the length $PP''$.`, model: J([r`**(a)** $P'${ct(pl1b)}$ and $Q'${ct(ql1b)}$ (the sign of the $x$-coordinate changes).`, r`**(b)** $PP'$ and $QQ'$ are both horizontal, so they are parallel; $PQ = P'Q'$ because a reflection keeps lengths. So $PQQ'P'$ is an isosceles trapezium. $PP' = ${wl1.lines[0]}$, $QQ' = ${wl1.lines[1]}$, and the distance between them is ${wl1.md[2]}. Area $= ${wl1.lines[3]}$ square units.`, r`**(c)** $P''${ct(pl1c)}$. Both coordinates of $P$ have changed sign, so the single transformation is reflection in the origin. $O$ is the midpoint of $PP''$ and $OP = ${wl1.lines[4]}$, so $PP'' = ${wl1.lines[5]}$ units.`]), sol: 'Reflect each point with the y-axis rule; the parallel sides of the trapezium are the horizontal segments PP′ and QQ′; two reflections in the axes make one reflection in the origin.', scheme: [["(a) P′(−4, 3), Q′(−1, −2) and the plot", 3], ['(b) isosceles trapezium with reason', 1], ['(b) parallel sides 8 and 2, height 5', 1], ['(b) area 25 square units', 1], ["(c) P″(−4, −3)", 1], ['(c) reflection in the origin', 1], ["(c) PP″ = 10 units", 2]], d: 3, c: 'application', t: [1, 3], time: 600 }), (C) => { wl1.verify(C); C.assert(classify(tl1) === 'isosceles trapezium' && area(tl1) === 25, 'isosceles trapezium, area 25'); C.assert(same(pl1c, img(O, pl1)) && dist(pl1, pl1c) === 10, 'origin; PP″ = 10'); C.model([ct([-4, 3]), ct([-1, -2]), 25, ct([-4, -3]), 10]); });

const al2 = P(-3, 2), bl2 = img(vx(1), al2), cl2 = img(hy(-1), bl2), dl2 = img(hy(-1), al2);
const wl2 = A([tw(1, -3), tw(-1, 2), r`5 - (-3) = 8`, r`2 - (-4) = 6`, r`\dfrac{1}{2} \times 8 \times 6 = 24`, r`2 \times (8 + 6) = 28`, r`\sqrt{8^2 + 6^2} = \sqrt{100} = 10`]);
Q('l02', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) The point $A(-3, 2)$ is reflected in the line $x = 1$ to $B$, and $B$ is reflected in the line $y = -1$ to $C$. Write the coordinates of $B$ and $C$.
(b) Name triangle $ABC$ and find its area.
(c) $D$ is the image of $A$ in the line $y = -1$. Name the quadrilateral $ABCD$, find its perimeter, and find the length of the diagonal $AC$.`, model: J([r`**(a)** In $x = 1$ the new $x$-coordinate is ${wl2.md[0]}, so $B${ct(bl2)}$. In $y = -1$ the new $y$-coordinate is ${wl2.md[1]}, so $C${ct(cl2)}$.`, r`**(b)** $AB$ is horizontal and $BC$ is vertical, so the angle at $B$ is a right angle: $ABC$ is a right-angled triangle. $AB = ${wl2.lines[2]}$, $BC = ${wl2.lines[3]}$, and the area is ${wl2.md[4]} square units.`, r`**(c)** $D${ct(dl2)}$. All four angles of $ABCD$ are right angles and $AB \ne BC$, so $ABCD$ is a rectangle. Perimeter $= ${wl2.lines[5]}$ units. $AC = ${wl2.lines[6]}$ units.`]), sol: 'Use (2a − x, y) for x = a and (x, 2b − y) for y = b; a horizontal and a vertical side meet at a right angle; the diagonal comes from Pythagoras.', scheme: [['(a) B(5, 2)', 2], ['(a) C(5, −4)', 1], ['(b) right-angled at B', 1], ['(b) area 24 square units', 2], ['(c) D(−3, −4) and rectangle', 2], ['(c) perimeter 28 units and AC = 10 units', 2]], d: 3, c: 'application', t: [2, 3], time: 600 }), (C) => { wl2.verify(C); C.assert(classify([al2, bl2, cl2]) === 'right-angled triangle' && area([al2, bl2, cl2]) === 24, 'triangle'); const q = [al2, bl2, cl2, dl2]; C.assert(classify(q) === 'rectangle' && perimeter(q) === 28 && dist(al2, cl2) === 10, 'rectangle, perimeter, diagonal'); C.model([ct([5, 2]), ct([5, -4]), 24, ct([-3, -4]), 28, 10]); });

const pl3 = img(X, P(5, -3)), ppl3 = img(vx(2), pl3), ml3 = mid(pl3, ppl3), tl3 = [pl3, P(5, -3), ppl3];
const wl3 = A([tw(2, 5), r`3 - (-3) = 6`, r`5 - (-1) = 6`, r`\dfrac{1}{2} \times 6 \times 6 = 18`]);
Q('l03', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) The point $P(a, b)$ is reflected in the $x$-axis to $P'(5, -3)$. Find $a$ and $b$.
(b) Write the image $P''$ of $P$ in the line $x = 2$. Find the point where the segment $PP''$ meets the line $x = 2$, and say why that point is invariant under this reflection.
(c) Name triangle $PP'P''$, giving a reason, and find its area.`, model: J([r`**(a)** Reflecting $P'$ back in the $x$-axis gives $P${ct(pl3)}$, so $a = 5$ and $b = 3$.`, r`**(b)** New $x$-coordinate: ${wl3.md[0]}, so $P''${ct(ppl3)}$. The line $x = 2$ is the perpendicular bisector of $PP''$, so they meet at the midpoint $${ct(ml3)}$. It lies on the mirror, and points on the mirror are invariant.`, r`**(c)** $PP'$ is vertical and $PP''$ horizontal, so the angle at $P$ is a right angle. $PP' = ${wl3.lines[1]}$ and $PP'' = ${wl3.lines[2]}$ are equal, so $PP'P''$ is a right-angled isosceles triangle. Area $= ${wl3.lines[3]}$ square units.`]), sol: 'Undo the x-axis reflection to find P; the mirror x = 2 bisects PP″ at right angles; the two legs from P are perpendicular and equal.', scheme: [['(a) a = 5, b = 3', 3], ["(b) P″(−1, 3)", 1], ['(b) meeting point (2, 3)', 1], ['(b) invariant because it is on the mirror', 1], ['(c) right-angled isosceles triangle with reason', 2], ['(c) area 18 square units', 2]], d: 3, c: 'application', t: [1, 2, 3], time: 600 }), (C) => { wl3.verify(C); C.assert(is(pl3, [5, 3]) && is(ppl3, [-1, 3]) && is(ml3, [2, 3]) && same(img(vx(2), P(...ml3)), P(...ml3)), 'P, P″, invariant midpoint'); C.assert(classify(tl3) === 'right-angled isosceles triangle' && area(tl3) === 18, 'triangle'); C.model([5, 3, ct([-1, 3]), ct([2, 3]), 18]); });

const al4 = P(-3, 4), [, a1l4, a2l4] = path(al4, Y, X), a3l4 = img(O, al4), tl4 = [al4, a1l4, a2l4];
const wl4 = A([r`3 - (-3) = 6`, r`4 - (-4) = 8`, r`\dfrac{1}{2} \times 6 \times 8 = 24`, r`\sqrt{6^2 + 8^2} = \sqrt{100} = 10`]);
Q('l04', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) $A(-3, 4)$ is reflected in the $y$-axis to $A_1$, and $A_1$ is reflected in the $x$-axis to $A_2$. Write the coordinates of $A_1$ and $A_2$.
(b) $A_3$ is the image of $A$ under reflection in the origin. Write $A_3$, compare it with $A_2$, and state the single transformation equivalent to the two reflections in (a).
(c) Name triangle $AA_1A_2$, and find its area and the length $AA_2$.`, model: J([r`**(a)** $A_1${ct(a1l4)}$ and $A_2${ct(a2l4)}$.`, r`**(b)** $A_3${ct(a3l4)}$, the same point as $A_2$. So reflection in the $y$-axis followed by reflection in the $x$-axis is equivalent to a single reflection in the origin.`, r`**(c)** $AA_1$ is horizontal and $A_1A_2$ is vertical, so $AA_1A_2$ is a right-angled triangle with the right angle at $A_1$. $AA_1 = ${wl4.lines[0]}$ and $A_1A_2 = ${wl4.lines[1]}$, so its area is ${wl4.md[2]} square units, and $AA_2 = ${wl4.lines[3]}$ units.`]), sol: 'Apply the axis rules in turn; both signs change, which is the rule for the origin; the legs of the triangle are the horizontal and vertical moves.', scheme: [['(a) A₁(3, 4)', 2], ['(a) A₂(3, −4)', 1], ['(b) A₃(3, −4) = A₂', 1], ['(b) reflection in the origin', 2], ['(c) right-angled at A₁', 1], ['(c) area 24 square units', 2], ['(c) AA₂ = 10 units', 1]], d: 2, c: 'application', t: [1, 2, 3], time: 600 }), (C) => { wl4.verify(C); C.assert(same(a2l4, a3l4) && singleFor(Y, X).eq === 'O', 'A₂ = A₃; origin'); C.assert(classify(tl4) === 'right-angled triangle' && area(tl4) === 24 && dist(al4, a2l4) === 10, 'triangle'); C.model([ct([3, 4]), ct([3, -4]), 24, 10]); });

const kl5 = { A: P(6, 0), B: P(3, 4), C: P(-3, 0) }, dl5 = img(X, kl5.B), fl5 = [kl5.A, kl5.B, kl5.C, dl5];
const wl5 = A([r`\sqrt{3^2 + 4^2} = 5`, r`6 - (-3) = 9`, r`4 - (-4) = 8`, r`\dfrac{1}{2} \times 9 \times 8 = 36`, r`2 \times \dfrac{1}{2} \times 9 \times 4 = 36`]);
Q('l05', mk.long({ marks: 10, stem: r`Use graph paper for this question (take $1$ cm $= 1$ unit on both axes).
(a) Plot $A(6, 0)$, $B(3, 4)$ and $C(-3, 0)$. Reflect $B$ in the $x$-axis to get $D$, and write its coordinates. Which of the points $A$, $B$, $C$ are invariant under this reflection?
(b) Name the quadrilateral $ABCD$, giving a reason.
(c) Find the length $AB$ and the area of $ABCD$.`, model: J([r`**(a)** $D${ct(dl5)}$. $A$ and $C$ lie on the $x$-axis, the mirror, so they are invariant; $B$ is not.`, r`**(b)** The mirror maps $B$ to $D$ and fixes $A$ and $C$, so $AB = AD$ and $CB = CD$: two pairs of equal adjacent sides. As $AB \ne CB$, $ABCD$ is a kite (with $AC$ as its axis of symmetry).`, r`**(c)** $AB = ${wl5.lines[0]}$ units. The diagonals are $AC = ${wl5.lines[1]}$ and $BD = ${wl5.lines[2]}$, and they are perpendicular, so the area is ${wl5.md[3]} square units. (Check: triangles $ABC$ and $ADC$ each have base $9$ and height $4$: ${wl5.md[4]}.)`]), sol: 'Points on the mirror are invariant; a figure made of a point, its image and two invariant points is symmetric about the mirror; a kite has perpendicular diagonals, so its area is half their product.', scheme: [['(a) D(3, −4)', 1], ['(a) A and C invariant', 2], ['(b) kite with reason', 3], ['(c) AB = 5 units', 1], ['(c) diagonals 9 and 8', 1], ['(c) area 36 square units', 2]], d: 4, c: 'analysis', t: [1, 3], time: 600 }), (C) => { wl5.verify(C); C.assert(same(img(X, kl5.A), kl5.A) && same(img(X, kl5.C), kl5.C) && !same(img(X, kl5.B), kl5.B), 'A, C invariant'); C.assert(classify(fl5) === 'kite' && area(fl5) === 36 && dist(kl5.A, kl5.B) === 5 && dist2(kl5.C, kl5.B) !== 25, 'kite, area, AB'); C.model([ct([3, -4]), 5, 36]); });

const ll6 = mirrorsOf(P(-2, 7), P(-2, -1)), l6 = ll6[0], ql6 = img(l6, P(5, -2)), wl6 = A([r`\dfrac{7 + (-1)}{2} = 3`, tw(3, -2)]), wl6b = W(eqctx('k', [1]), [r`k + 2 = 3 \Rightarrow k = 1`]), wl6c = A([r`2 \times 1 - 1 = 1`]);
Q('l06', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) The image of $P(-2, 7)$ in a line $l$ is $P'(-2, -1)$. Find the equation of $l$.
(b) Find the images of $Q(5, -2)$ and $R(-4, 3)$ in $l$. What do you notice about $R$?
(c) The point $(2k - 1, k + 2)$ is invariant under reflection in $l$. Find $k$, the point, and the image of the point in the origin.`, model: J([r`**(a)** $P$ and $P'$ have the same $x$-coordinate, so $l$ is horizontal, halfway between them: ${wl6.md[0]}. So $l$ is $y = 3$.`, r`**(b)** For $Q$ the new $y$-coordinate is ${wl6.md[1]}, so its image is $${ct(ql6)}$. $R$ has $y$-coordinate $3$, so it lies on $l$: its image is $${ct(img(l6, P(-4, 3)))}$ itself, an invariant point.`, r`**(c)** An invariant point lies on $l$, so its $y$-coordinate is $3$: ${wl6b.md[0]}. Its $x$-coordinate is then ${wl6c.md[0]}, so the point is $(1, 3)$, and its image in the origin is $${ct(img(O, P(1, 3)))}$.`]), sol: 'The mirror is the perpendicular bisector of PP′; a point is invariant exactly when it lies on the mirror.', scheme: [['(a) mirror horizontal through the midpoint', 1], ['(a) l: y = 3', 2], ['(b) Q′(5, 8)', 2], ['(b) R invariant, on l', 1], ['(c) k + 2 = 3, so k = 1', 2], ['(c) point (1, 3) and image (−1, −3)', 2]], d: 3, c: 'application', t: [2, 3], time: 600 }), (C) => { wl6.verify(C); wl6b.verify(C); wl6c.verify(C); C.assert(ll6.length === 1 && l6.eq === 'y = 3' && is(ql6, [5, 8]) && same(img(l6, P(-4, 3)), P(-4, 3)), 'l, Q′, R fixed'); const k = 1; C.assert(same(img(l6, P(2 * k - 1, k + 2)), P(2 * k - 1, k + 2)), 'invariant at k = 1'); C.model(['y = 3', ct([5, 8]), ct([-4, 3]), ct([1, 3]), ct([-1, -3])]); });

const tl7 = [P(1, 1), P(4, 1), P(4, 5)], il7 = imgAll(Y, tl7), rl7 = [tl7[1], tl7[2], il7[2], il7[1]];
const wl7 = A([r`4 - (-4) = 8`, r`5 - 1 = 4`, r`8 \times 4 = 32`, r`\sqrt{3^2 + 4^2} = 5`, r`3 + 4 + 5 = 12`, r`\dfrac{1}{2} \times 3 \times 4 = 6`]);
Q('l07', mk.long({ marks: 10, stem: r`Use graph paper for this question (take $1$ cm $= 1$ unit on both axes).
(a) Draw triangle $ABC$ with $A(1, 1)$, $B(4, 1)$ and $C(4, 5)$. Reflect it in the $y$-axis and write the vertices of its image $A'B'C'$.
(b) Name the quadrilateral $BCC'B'$ and find its area.
(c) Find the perimeter and the area of triangle $ABC$. Without measuring, state the perimeter and area of $A'B'C'$, giving a reason.`, model: J([r`**(a)** $A'${ct(il7[0])}$, $B'${ct(il7[1])}$, $C'${ct(il7[2])}$.`, r`**(b)** $BC$ and $B'C'$ are vertical, $CC'$ and $BB'$ horizontal, so every angle is a right angle; $BB' = ${wl7.lines[0]}$ and $BC = ${wl7.lines[1]}$ are unequal, so $BCC'B'$ is a rectangle. Area $= ${wl7.lines[2]}$ square units.`, r`**(c)** $AB = 3$, $BC = 4$ and $AC = ${wl7.lines[3]}$, so the perimeter is ${wl7.md[4]} units, and the area is ${wl7.md[5]} square units (right angle at $B$). Triangle $A'B'C'$ also has perimeter $12$ units and area $6$ square units, because a reflection does not change lengths: the image is congruent to $ABC$.`]), sol: 'Reflect each vertex in the y-axis; vertical and horizontal sides give right angles; a reflection keeps every length, so the image triangle is congruent.', scheme: [["(a) A′(−1, 1), B′(−4, 1), C′(−4, 5)", 3], ['(b) rectangle with reason', 1], ['(b) area 32 square units', 2], ['(c) perimeter 12 units', 1], ['(c) area 6 square units', 1], ['(c) same for the image, with reason', 2]], d: 2, c: 'application', t: [1, 3], time: 600 }), (C) => { wl7.verify(C); C.assert(classify(rl7) === 'rectangle' && area(rl7) === 32, 'rectangle 32'); C.assert(perimeter(tl7) === 12 && perimeter(il7) === 12 && area(tl7) === 6 && area(il7) === 6, 'congruent'); C.model([ct([-1, 1]), ct([-4, 1]), ct([-4, 5]), 32, 12, 6]); });
